defineProps<{ badge: { id: string; event_id: string; code: string; status: string; lot: string; category: string | null; reserved_device_id: string | null; reserved_group_id: string | null; printed_for_visitor_id: string | null }; transfers: { id: string; from_name: string; to_name: string; reservation_released: boolean; created_at: string }[]; history: { id: string; visitor_id: string; event_name: string; person_id: string; person_name: string; actor_id: string | null; assigned_at: string; returned_at: string | null; cancelled_at: string | null }[] }>();
