ata-testid="mise-a-disposition">De « {{ t.from_name }} » vers « {{ t.to_name }} » le {{ t.created_at }}<template v-if="t.reservation_released"> · réservation précédente levée</template></li></ul></section><Link href="/administration/badges/registre" class="btn-soft">Registre commun des badges</Link> <Link href="/administration/badges" class="btn-soft">Revenir aux badges</Link></AdminLayout></template>
